PER_STEP = -1.0

def partial(gamma, steps):
    total = 0.0
    for t in range(steps):
        total = total + (gamma ** t) * PER_STEP
    return total

def closed_form(gamma):
    if gamma < 1.0:
        limit = PER_STEP / (1.0 - gamma)
    else:
        limit = float('-inf')
    return limit

for gamma in (1.0, 0.99):
    print("gamma", gamma, "limit", round(closed_form(gamma), 4))
    for steps in (100, 1000, 10000):
        print("   after", steps, "steps", round(partial(gamma, steps), 4))

ARENA_DISTANCE = 8

def route_return(n, payout, step_cost, gamma):
    rewards = [step_cost] * (n - 1) + [payout]
    g = 0.0
    for r in reversed(rewards):
        g = r + gamma * g
    return g

def reach(gamma, payout=10.0, step_cost=-1.0):
    n = 1
    while route_return(n + 1, payout, step_cost, gamma) > 0.0:
        n = n + 1
    return n

for gamma in (0.5, 0.8, 0.9, 0.95, 0.99):
    r = reach(gamma)
    print("gamma", gamma, "reach", r, "cells", "covers the arena", r >= ARENA_DISTANCE)

